DataGeneratorTransactions = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=DataGeneratorTransactions]");
        var apps = await model.getDatasource({ endpoint: "ContentManagement/App" })
        var formModel = new kendo.data.ObservableObject({
            App: null,
            SourceSystemId: null,
            NumberOfInvoices: null,
            NumberOfCredits: null,
            NumberOfRemittanceAdvices: null,
            NumberOfOffers: null,
            CurrencyId: "EUR",
            MasterdataDMSPath: null
        });

        kendo.bind(container, formModel);
        container.data("model", formModel);
        $("[name=app]", container).kendoDropDownList({
            optionLabel: "[resource_displayname[App]]",
            dataTextField: "Name",
            dataValueField: "Id",
            dataSource: apps
        }).data("kendoDropDownList");
        $("[name=build]", container).on("click", function () {
            DataGeneratorTransactions.build(app, formModel);
        });
    },

    build: async function (app, model) {
        var appInfo = await api.get("ContentManagement/App(" + model.App.Id + ")");
        model.SourceSystemId = JSON.parse(appInfo.ConfigJson).B2B.SourceSystem;
        var functions = {
            [dms[Scripts/generateData.js]]
        };
        var vars = {
            MasterdataDMSPath: model.MasterdataDMSPath,
            SourceSystemId: model.SourceSystemId,
            CurrencyId: model.CurrencyId,
            NumberOfInvoices: model.NumberOfInvoices,
            NumberOfCredits: model.NumberOfCredits,
            NumberOfRemittanceAdvices: model.NumberOfRemittanceAdvices,
            NumberOfOffers: model.NumberOfOffers,
            AppId: appInfo.Id,
            OfferStates: DataGeneratorTransactions.OfferStates
        };
        var d = new Dialog({
            width: 800,
            height: 500
        });
        d.init(() => {
            loadComponent($(d.element), "ScriptRunner", (component) => {
                component.init(app, d.element, vars, functions, d);
            });
        });
    },

    offerStates: {
        None: "",
        Proposed: "[resource_displayname[proposed]]",
        Received: "[resource_displayname[received]]",
        ForApproval: "[resource_displayname[forapproval]]",
        Approved: "[resource_displayname[approved]]",
        Sent: "[resource_displayname[sent]]",
        Held: "[resource_displayname[held]]",
        Paid: "[resource_displayname[paid]]",
        SentForFunding: "[resource_displayname[sentforfunding]]",
        FundingProposed: "[resource_displayname[fundingproposed]]",
        FundingAccepted: "[resource_displayname[fundingaccepted]]",
        FundingRejected: "[resource_displayname[fundingrejected]]",
        Funded: "[resource_displayname[funded]]",
        RejectedCancelled: "[resource_displayname[rejectedcancelled]]",
        Archived: "[resource_displayname[archived]]",
        Complete: "[resource_displayname[complete]]",
        OfferedtoFunder: "[resource_displayname[offeredToFunder]]",
        DiscountProposed: "[resource_displayname[DiscountProposed]]"
    }
}
